"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ShieldCheckIcon as PhShield, ArrowCounterClockwiseIcon as PhReset } from "@phosphor-icons/react";

interface GrantDef {
  id: string;
  label: string;
  detail: string;
  grantedLabel: string;
}

const GRANTS: GrantDef[] = [
  { id: "calendar-read", label: "Read your events", detail: "Sees event titles, times, and attendees.", grantedLabel: "Granted 12 days ago" },
  { id: "calendar-write", label: "Create and edit events", detail: "Adds, moves, or cancels events for you.", grantedLabel: "Granted 12 days ago" },
  { id: "contacts-read", label: "Read your contacts", detail: "Looks up names to suggest attendees.", grantedLabel: "Granted 5 days ago" },
  { id: "location", label: "Read your location", detail: "Suggests nearby meeting spots.", grantedLabel: "Granted 2 days ago" },
];

interface FeatureDef {
  id: string;
  label: string;
  requires: string[];
}

const FEATURES: FeatureDef[] = [
  { id: "smart-scheduling", label: "Smart scheduling", requires: ["calendar-read", "calendar-write"] },
  { id: "attendee-suggestions", label: "Attendee name suggestions", requires: ["calendar-read", "contacts-read"] },
  { id: "nearby-spots", label: "Nearby meeting spot suggestions", requires: ["calendar-write", "location"] },
];

function ShieldIcon() {
  return <PhShield size={15} aria-hidden />;
}
function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

function labelFor(id: string) {
  return GRANTS.find((g) => g.id === id)?.label ?? id;
}

function initialActive(): Record<string, boolean> {
  return Object.fromEntries(GRANTS.map((g) => [g.id, true]));
}

interface ConsentLedgerProps {
  className?: string;
}

export function ConsentLedger({ className }: ConsentLedgerProps) {
  const [active, setActive] = useState<Record<string, boolean>>(initialActive);
  const shouldReduceMotion = useReducedMotion();

  const toggle = (id: string) => {
    setActive((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const reset = () => {
    setActive(initialActive());
  };

  const activeCount = Object.values(active).filter(Boolean).length;

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
            <ShieldIcon />
            Permissions
          </h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset all permissions"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        <p className="mt-1 flex items-center gap-1 text-xs text-slate-400 dark:text-slate-500">
          <span className="relative inline-block h-[1.4em] w-3 align-middle">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={activeCount}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -8 }}
                transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
                className="absolute inset-0 flex items-center justify-center font-semibold text-slate-600 dark:text-slate-300"
              >
                {activeCount}
              </motion.span>
            </AnimatePresence>
          </span>
          of {GRANTS.length} permissions active, revoke any of them right here
        </p>

        <div className="mt-3 space-y-1.5">
          {GRANTS.map((g) => {
            const on = active[g.id];
            return (
              <div key={g.id} className="rounded-lg p-2 transition-colors">
                <div className="flex items-start gap-2.5">
                  <motion.button
                    type="button"
                    role="switch"
                    aria-checked={on}
                    aria-label={g.label}
                    onClick={() => toggle(g.id)}
                    whileTap={shouldReduceMotion ? undefined : { scale: 0.93 }}
                    className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                      on ? "bg-emerald-600" : "bg-slate-300 dark:bg-slate-600"
                    }`}
                  >
                    <motion.span
                      animate={{ x: on ? 17 : 2 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 700, damping: 32 }}
                      className="absolute top-0.5 block h-4 w-4 rounded-full bg-white shadow-sm"
                    />
                  </motion.button>
                  <span className="min-w-0 flex-1">
                    <span
                      className={`block text-xs font-medium transition-colors ${
                        on ? "text-slate-800 dark:text-slate-100" : "text-slate-400 line-through dark:text-slate-600"
                      }`}
                    >
                      {g.label}
                    </span>
                    <span className="block text-[11px] text-slate-500 dark:text-slate-400">
                      {on ? g.grantedLabel : "Revoked, flip it back to restore."}
                    </span>
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-4 rounded-xl border border-slate-200/70 bg-slate-50/70 p-3.5 dark:border-white/10 dark:bg-white/[0.03]">
          <p className="text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
            What this powers right now
          </p>
          <div className="mt-2 space-y-1.5">
            {FEATURES.map((f) => {
              const unlocked = f.requires.every((id) => active[id]);
              const missing = f.requires.filter((id) => !active[id]);
              return (
                <div key={f.id} className="text-xs">
                  <span className="relative inline-block">
                    <span className={unlocked ? "text-slate-700 dark:text-slate-200" : "text-slate-400 dark:text-slate-500"}>
                      {f.label}
                    </span>
                    <motion.span
                      aria-hidden
                      className="absolute left-0 top-1/2 h-px w-full origin-left bg-slate-400 dark:bg-slate-500"
                      animate={{ scaleX: unlocked ? 0 : 1 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                    />
                  </span>
                  {!unlocked && (
                    <span className="ml-1.5 text-[11px] text-slate-400 dark:text-slate-500">
                      needs {missing.map(labelFor).join(", ")}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Every grant is revocable in place, and revoking one instantly shows which features actually depended on it, no settings sub-menu required.
      </p>
    </div>
  );
}
